#!/bin/bash
# Kansas City run registry adds, part 5 of 10. Run once from the registry folder after: source ./.env
ADDED=0; REFUSED=0; REFUSED_LIST=""
if python3 registry.py add --slug candyland-christmas-and-lighted-christmas-parade-in-downtown-smithville-mo --name 'CandyLand Christmas and Lighted Christmas Parade in Downtown Smithville' --city Smithville --cc mo --url https://www.smithvillechamber.org/communitycalendar --date 2026-12-05 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST candyland-christmas-and-lighted-christmas-parade-in-downtown-smithville-mo"; fi || true
if python3 registry.py add --slug storytime-with-santa-and-mrs-claus-at-smithville-library-mo --name 'Storytime with Santa and Mrs. Claus at Smithville Library' --city Smithville --cc mo --url https://www.mymcpl.org/events/122497/storytime-santa-and-mrs-claus --date 2026-12-17 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST storytime-with-santa-and-mrs-claus-at-smithville-library-mo"; fi || true
